<ellipse cx="180" cy="155" rx="140" ry="18" fill="#a0b0d0" opacity="0.06" filter="url(#mistBlur)"><animate attributeName="cx" values="180;200;180" dur="12s" repeatCount="indefinite"/></ellipse>
